/// Filename detection: `pmacs.parse.language_from_filename` maps a
/// basename (Dockerfile / Makefile / CMakeLists.txt / rc dotfiles) to a
/// language, resolving a full path too, and returns nil for a plain file.
/// The default bundle also wires the dockerfile and cmake LSP configs;
/// Make has no server, so `config.make` is absent.
#[test]
fn m4_filename_map_resolves_special_files() {
    use pmacs::editor::EditorState;
    let s = EditorState::new_with_roots(&crate::iso::roots());
    let probe: mlua::Table = s
        .lua_host
        .lua()
        .load(
            r"
            local f = pmacs.parse.language_from_filename
            local out = {}
            out.dockerfile = f('Dockerfile')
            out.containerfile = f('Containerfile')
            out.make = f('Makefile')
            out.gnumake = f('GNUmakefile')
            out.cmake = f('CMakeLists.txt')
            out.bashrc = f('.bashrc')
            out.pkgbuild = f('PKGBUILD')
            out.pathform = f('/home/x/proj/Dockerfile')
            out.plain_is_nil = f('notes.txt') == nil
            out.cfg_docker = pmacs.lsp.config.dockerfile and pmacs.lsp.config.dockerfile.command
            out.cfg_cmake = pmacs.lsp.config.cmake and pmacs.lsp.config.cmake.command
            -- cmake-language-server reads buildDirectory from
            -- initializationOptions, not workspace/configuration.
            out.cmake_builddir = pmacs.lsp.config.cmake
                and pmacs.lsp.config.cmake.init_options
                and pmacs.lsp.config.cmake.init_options.buildDirectory
            out.has_make_cfg = pmacs.lsp.config.make ~= nil
            return out
            ",
        )
        .eval()
        .expect("probe filename map");
    assert_eq!(probe.get::<String>("dockerfile").unwrap(), "dockerfile");
    assert_eq!(probe.get::<String>("containerfile").unwrap(), "dockerfile");
    assert_eq!(probe.get::<String>("make").unwrap(), "make");
    assert_eq!(probe.get::<String>("gnumake").unwrap(), "make");
    assert_eq!(probe.get::<String>("cmake").unwrap(), "cmake");
    assert_eq!(probe.get::<String>("bashrc").unwrap(), "bash");
    assert_eq!(probe.get::<String>("pkgbuild").unwrap(), "bash");
    assert_eq!(
        probe.get::<String>("pathform").unwrap(),
        "dockerfile",
        "basename is extracted from a full path"
    );
    assert!(probe.get::<bool>("plain_is_nil").unwrap());
    assert_eq!(
        probe.get::<String>("cfg_docker").unwrap(),
        "docker-langserver"
    );
    assert_eq!(
        probe.get::<String>("cfg_cmake").unwrap(),
        "cmake-language-server"
    );
    assert_eq!(
        probe.get::<String>("cmake_builddir").unwrap(),
        "build",
        "cmake config passes buildDirectory via init_options (not a workspace/configuration section)"
    );
    assert!(
        !probe.get::<bool>("has_make_cfg").unwrap(),
        "Make has no language server, so no config.make"
    );
}

/// End-to-end: opening an extensionless `Dockerfile` attaches the
/// dockerfile grammar (a settled parse tree) and resolves `dockerfile`
/// for LSP — reachable only via the filename map, since the file has no
/// extension and no shebang. `pmacs.lsp.config` is emptied first so
/// docker-langserver is not spawned; grammar detection is independent.
#[test]
fn m4_filename_extensionless_dockerfile_highlights() {
    use pmacs::editor::EditorState;
    let mut s = EditorState::new_with_roots(&crate::iso::roots());
    let dir = tempfile::tempdir().expect("tempdir");
    let f = dir.path().join("Dockerfile"); // no extension
    std::fs::write(&f, b"FROM alpine:3\nRUN apk add curl\n").expect("write");
    let f_disp = f.display();
    s.lua_host
        .lua()
        .load(format!(
            "pmacs.lsp.config = {{}}
             pmacs.buffer.find_or_open('{f_disp}')"
        ))
        .exec()
        .expect("open Dockerfile");
    let lsp_lang: Option<String> = s
        .lua_host
        .lua()
        .load("return pmacs.lsp.active_buffer_language()")
        .eval()
        .expect("lsp language");
    assert_eq!(
        lsp_lang.as_deref(),
        Some("dockerfile"),
        "extensionless Dockerfile resolves to dockerfile for LSP"
    );
    pump_async(&mut s, |st| current_tree_language(st).is_some());
    assert_eq!(
        current_tree_language(&s).as_deref(),
        Some("dockerfile"),
        "extensionless Dockerfile gets a dockerfile parse tree"
    );
}

/// Grammar-gap languages: each bundled grammar's name matches the
/// existing `pmacs.lsp.config.<name>` key, so grammar detection (which
/// wins over the filetype map) resolves the id the server keys off — the
/// file now gets BOTH highlighting and the right server. Verified through
/// the loaded runtime.
#[test]
fn m4_gap_grammars_align_with_lsp_configs() {
    use pmacs::editor::EditorState;
    let s = EditorState::new_with_roots(&crate::iso::roots());
    for (path, id) in [
        ("app.py", "python"),
        ("srv.go", "go"),
        ("m.js", "javascript"),
        ("v.jsx", "javascriptreact"),
        ("i.ts", "typescript"),
        ("A.tsx", "typescriptreact"),
        ("Cargo.toml", "toml"),
        ("build.zig", "zig"),
        ("tsconfig.json", "json"),
        ("config.yaml", "yaml"),
        ("ci.yml", "yaml"),
    ] {
        let (grammar, has_cfg): (Option<String>, bool) = s
            .lua_host
            .lua()
            .load(format!(
                "return pmacs.parse.language_for_path('{path}'),
                        pmacs.lsp.config['{id}'] ~= nil"
            ))
            .eval()
            .unwrap_or_else(|e| panic!("probe {path}: {e}"));
        assert_eq!(
            grammar.as_deref(),
            Some(id),
            "{path} grammar detection resolves to {id}"
        );
        assert!(
            has_cfg,
            "{id} has an LSP config the grammar name aligns with"
        );
    }
}

/// JSON/YAML LSP configs pin the server commands and the settings shape
/// each consumes (framing Q#JY2): JSON receives a pushed full object;
/// YAML pulls five named sections. The pinned JSON and YAML providers each
/// have a separate PATH-gated live smoke below. The point is to pin the
/// contract, not merely assert that some settings table exists.
#[test]
fn m4_json_yaml_lsp_configs_pin_command_and_sections() {
    use pmacs::editor::EditorState;
    let s = EditorState::new_with_roots(&crate::iso::roots());
    let lua = s.lua_host.lua();

    // json: the `@t1ckbase/vscode-langservers-extracted@2.0.2` binary
    // (NOT the stale standalone `vscode-json-languageserver`), `--stdio`,
    // and the `json` + `http` workspace-config sections present. The
    // provider preserves this stable command name; its exact pin and live
    // handshake evidence are documented beside the default config.
    let json_command: String = lua
        .load("return pmacs.lsp.config.json.command")
        .eval()
        .unwrap();
    assert_eq!(
        json_command, "vscode-json-language-server",
        "json uses the pinned T1ckbase provider's stable command name"
    );
    // The JSON server is push-model (reads didChangeConfiguration, no
    // pulls), so `json.validate.enable` must be EXPLICITLY true — a missing
    // value reads as false and disables validation. Remote schemas left on.
    let json_ok: bool = lua
        .load(
            "local c = pmacs.lsp.config.json
             return c.args[1] == '--stdio'
                 and c.settings.json.validate.enable == true
                 and c.settings.http ~= nil
                 and c.settings.handledSchemaProtocols == nil",
        )
        .eval()
        .unwrap();
    assert!(
        json_ok,
        "json config: --stdio, json.validate.enable=true, http present, remote schemas on"
    );

    // yaml: `yaml-language-server --stdio`. Its settings handler reads the
    // `yaml`, `http`, `[yaml]`, `editor`, and `files` sections — pin all
    // five, and confirm the inert `redhat.telemetry` is NOT shipped (the
    // standalone server emits telemetry events to the client; it does not
    // upload, and pmacs has no uploader).
    let yaml_command: String = lua
        .load("return pmacs.lsp.config.yaml.command")
        .eval()
        .unwrap();
    assert_eq!(
        yaml_command, "yaml-language-server",
        "yaml uses the Red Hat yaml-language-server"
    );
    let yaml_ok: bool = lua
        .load(
            "local c = pmacs.lsp.config.yaml
             return c.args[1] == '--stdio'
                 and c.settings.yaml ~= nil
                 and c.settings.http ~= nil
                 and c.settings['[yaml]'] ~= nil
                 and c.settings.editor ~= nil
                 and c.settings.files ~= nil
                 and c.settings.redhat == nil",
        )
        .eval()
        .unwrap();
    assert!(
        yaml_ok,
        "yaml config: --stdio, the five pulled sections present, no inert redhat.telemetry"
    );
}

/// Round-1 finding (P1): the daemon must PUSH configuration via
/// `workspace/didChangeConfiguration` after `initialized`. Push-model
/// servers — notably the VS Code JSON server — never issue
/// `workspace/configuration` pulls, so without the push their `settings`
/// (including `json.validate.enable`) are inert. Verified through the fake
/// server's config sink: the settings the daemon sends are recorded and
/// inspected, proving delivery end to end.
#[test]
fn m4_5_initial_config_pushed_via_did_change_configuration() {
    use pmacs::editor::EditorState;
    let mut state = EditorState::new_with_roots(&crate::iso::roots());
    let fake = fake_lsp_path();
    let dir = tempfile::tempdir().expect("tempdir");
    let sink = dir.path().join("config.jsonl");
    let file = dir.path().join("probe.rs");
    std::fs::write(&file, "fn main() {}\n").expect("write");
    let sink_disp = sink.display().to_string();
    let file_disp = file.display().to_string();

    // Point rust at the fake server WITH a settings table and route the
    // config sink into the spawned process, then open the file (auto-attach
    // → initialize → initialized → the config push).
    state
        .lua_host
        .lua()
        .load(format!(
            "pmacs.lsp.config.rust = {{
               command = '{fake}',
               env = {{ PMACS_FAKE_LSP_CONFIG_SINK = '{sink_disp}' }},
               settings = {{ rust = {{ probe = true }} }},
             }}
             pmacs.buffer.find_or_open('{file_disp}')"
        ))
        .exec()
        .expect("configure + open");

    assert!(
        pump_lua_flag(
            &mut state,
            "(function() for _,r in ipairs(pmacs.lsp.list()) do \
               if r.state and r.state.kind=='initialized' then return true end \
             end return false end)()",
            5,
        ),
        "fake never initialized"
    );
    // A few more ticks for the push + the server's sink write to land.
    //
    // Wait for a COMPLETE record, not for a substring of one. The sink is
    // JSONL written by a separate process (`writeln!` in
    // `src/bin/pmacs_fake_lsp.rs`, one line per push), so a substring
    // predicate can be satisfied by a half-written line and the assertion
    // below then reads the truncation. That is a real race, not a platform
    // quirk: `probe` lands six bytes before `"probe":true` is complete, and
    // macOS/lua54 lost it in CI, reporting `{"rust":{"probe":`.
    //
    // The trailing newline is the strongest available predicate because it
    // waits for exactly the unit the assertion reads, and it stays correct
    // if the payload's field order or spelling ever changes.
    let sink_probe = sink.clone();
    pump_async(&mut state, move |_| {
        std::fs::read_to_string(&sink_probe).is_ok_and(|s| s.ends_with('\n'))
    });

    let recorded = std::fs::read_to_string(&sink).unwrap_or_else(|e| {
        panic!("config sink not written ({e}); the didChangeConfiguration push did not arrive")
    });
    assert!(
        recorded.contains("\"probe\":true"),
        "the daemon pushed the configured settings after initialized: {recorded}"
    );
}

/// PATH-gated provider smoke: drive a real `vscode-json-language-server`
/// through pmacs's default JSON config, including the post-initialize
/// `didChangeConfiguration` push, and require a syntax diagnostic for an
/// invalid document. The reviewed provider is
/// `@t1ckbase/vscode-langservers-extracted@2.0.2`; CI skips cleanly when
/// no compatible binary is installed.
#[test]
fn m4_real_json_provider_receives_config_and_reports_diagnostics() {
    use pmacs::editor::EditorState;

    let Ok(command) = which_binary("vscode-json-language-server") else {
        support::skip_or_fail("vscode-json-language-server", "PMACS_REQUIRE_LSP");
        return;
    };
    let command = command.display().to_string();
    let dir = tempfile::tempdir().expect("tempdir");
    let file = std::fs::canonicalize(dir.path())
        .expect("canonicalize")
        .join("invalid.json");
    std::fs::write(&file, b"{\"broken\": }\n").expect("write invalid json");
    let file_disp = file.display().to_string();
    let uri = format!("file://{file_disp}");

    let mut state = EditorState::new_with_roots(&crate::iso::roots());
    state
        .lua_host
        .lua()
        .load(format!(
            "pmacs.lsp.config.json.command = '{command}'
             pmacs.buffer.find_or_open('{file_disp}')"
        ))
        .exec()
        .expect("configure real JSON server + open file");

    assert!(
        pump_lua_flag(
            &mut state,
            "(function() for _,r in ipairs(pmacs.lsp.list()) do \
               if r.state and r.state.kind=='initialized' then return true end \
             end return false end)()",
            30,
        ),
        "real JSON server never reached initialized"
    );

    let deadline = Instant::now() + Duration::from_secs(10);
    let mut got_diagnostic = false;
    while Instant::now() < deadline {
        state.tick_processes();
        state.tick_lsp();
        state.tick_async();
        got_diagnostic = state
            .lua_host
            .lua()
            .load(format!("return pmacs.diag.count('{uri}') > 0"))
            .eval()
            .unwrap_or(false);
        if got_diagnostic {
            break;
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    assert!(
        got_diagnostic,
        "real JSON server produced no diagnostic; config delivery or validation is broken"
    );
    assert_no_lsp_crash(&mut state, "real JSON server");
}

/// PATH-gated provider smoke: drive Red Hat
/// `yaml-language-server@1.24.0` through pmacs's default YAML config and
/// require a syntax diagnostic for an invalid document. `SchemaStore` and
/// the Kubernetes CRD catalog are disabled in this test so the result is
/// deterministic and does not depend on network access. CI skips cleanly
/// when no compatible binary is installed.
#[test]
fn m4_real_yaml_provider_pulls_config_and_reports_diagnostics() {
    use pmacs::editor::EditorState;

    let Ok(command) = which_binary("yaml-language-server") else {
        support::skip_or_fail("yaml-language-server", "PMACS_REQUIRE_LSP");
        return;
    };
    let command = command.display().to_string();
    let dir = tempfile::tempdir().expect("tempdir");
    let file = std::fs::canonicalize(dir.path())
        .expect("canonicalize")
        .join("invalid.yaml");
    std::fs::write(&file, b"root:\n  broken: [one,\n").expect("write invalid yaml");
    let file_disp = file.display().to_string();
    let uri = format!("file://{file_disp}");

    let mut state = EditorState::new_with_roots(&crate::iso::roots());
    state
        .lua_host
        .lua()
        .load(format!(
            "local c = pmacs.lsp.config.yaml
             c.command = '{command}'
             c.settings.yaml.schemaStore = {{ enable = false }}
             c.settings.yaml.kubernetesCRDStore = {{ enable = false }}
             pmacs.buffer.find_or_open('{file_disp}')"
        ))
        .exec()
        .expect("configure real YAML server + open file");

    assert!(
        pump_lua_flag(
            &mut state,
            "(function() for _,r in ipairs(pmacs.lsp.list()) do \
               if r.language_id=='yaml' and r.state \
                  and r.state.kind=='initialized' then return true end \
             end return false end)()",
            30,
        ),
        "auto-attached real YAML server never reached initialized"
    );

    let deadline = Instant::now() + Duration::from_secs(10);
    let mut got_diagnostic = false;
    while Instant::now() < deadline {
        state.tick_processes();
        state.tick_lsp();
        state.tick_async();
        got_diagnostic = state
            .lua_host
            .lua()
            .load(format!("return pmacs.diag.count('{uri}') > 0"))
            .eval()
            .unwrap_or(false);
        if got_diagnostic {
            break;
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    assert!(
        got_diagnostic,
        "real YAML server produced no diagnostic; config pulls or validation are broken"
    );
    assert_no_lsp_crash(&mut state, "real YAML server");
    let still_initialized: bool = state
        .lua_host
        .lua()
        .load(
            "for _,r in ipairs(pmacs.lsp.list()) do \
               if r.language_id=='yaml' and r.state \
                  and r.state.kind=='initialized' then return true end \
             end return false",
        )
        .eval()
        .expect("inspect YAML server state");
    assert!(
        still_initialized,
        "real YAML server did not remain alive after publishing diagnostics"
    );
}

/// Typing-perf: the default bundle coalesces full-document
/// `didChange` notifications instead of sending one per keystroke
/// (each send copies the whole buffer several times and writes
/// O(file) JSON to the server pipe). The after-edit hook only bumps
/// the version and records the buffer dirty; the notification ships
/// on the async tick after the quiet window, or synchronously when a
/// request path flushes via `pmacs.lsp._flush_did_changes`. Observed
/// by monkeypatching `pmacs.lsp.did_change` (the bundle resolves it
/// dynamically at flush time) and firing `buffer.after-edit` through
/// the public hook runner.
#[test]
fn m4_lua_bundle_debounces_did_change_per_keystroke() {
    use pmacs::editor::EditorState;

    let mut s = EditorState::new_with_roots(&crate::iso::roots());
    let fake = fake_lsp_path();
    let dir = tempfile::TempDir::new().unwrap();
    let file = dir.path().join("debounce.rs");
    std::fs::write(&file, "fn main() {}\n").unwrap();
    let file_disp = file.display();

    // Point the rust config at the fake server, open the file (the
    // after-load hook auto-attaches and sends didOpen v1), then
    // instrument did_change.
    s.lua_host
        .lua()
        .load(format!(
            "
            pmacs.lsp.config.rust = {{ command = '{fake}' }}
            pmacs.buffer.find_or_open('{file_disp}')
            _G.__sent_did_changes = {{}}
            local real = pmacs.lsp.did_change
            pmacs.lsp.did_change = function(sid, uri, version, text)
                table.insert(_G.__sent_did_changes, {{ version = version, len = #text }})
                return real(sid, uri, version, text)
            end
            "
        ))
        .exec()
        .expect("configure + open + instrument");

    // Three "keystrokes" in a burst: nothing may ship inline.
    s.lua_host
        .lua()
        .load("for _ = 1, 3 do pmacs.hook.run('buffer.after-edit') end")
        .exec()
        .expect("fire after-edit burst");
    let sent: i64 = s
        .lua_host
        .lua()
        .load("return #_G.__sent_did_changes")
        .eval()
        .expect("count sends");
    assert_eq!(sent, 0, "didChange must not ship per keystroke");

    // Request-path flush: exactly one coalesced notification carrying
    // the latest version (didOpen was v1, three edits bump to v4 —
    // skipped intermediate versions are legal, LSP only requires
    // strictly increasing).
    let (sent, version): (i64, i64) = s
        .lua_host
        .lua()
        .load(
            "
            pmacs.lsp._flush_did_changes()
            local n = #_G.__sent_did_changes
            local v = n > 0 and _G.__sent_did_changes[n].version or -1
            return n, v
            ",
        )
        .eval()
        .expect("flush + count");
    assert_eq!(
        sent, 1,
        "explicit flush ships exactly one coalesced didChange"
    );
    assert_eq!(
        version, 4,
        "flush carries the latest version (v1 open + 3 edits)"
    );

    // Time-based flush: one more edit, then tick after the quiet
    // window (75ms in the bundle) has elapsed.
    s.lua_host
        .lua()
        .load("pmacs.hook.run('buffer.after-edit')")
        .exec()
        .expect("fire single after-edit");
    std::thread::sleep(Duration::from_millis(120));
    s.tick_async();
    let (sent, version): (i64, i64) = s
        .lua_host
        .lua()
        .load(
            "
            local n = #_G.__sent_did_changes
            local v = n > 0 and _G.__sent_did_changes[n].version or -1
            return n, v
            ",
        )
        .eval()
        .expect("count after tick");
    assert_eq!(sent, 2, "quiet-window tick flushes the pending didChange");
    assert_eq!(version, 5, "tick flush carries the post-edit version");
}

/// Defensive: the auto-attach hook ignores buffers that don't have a
/// language config, doesn't crash on `*scratch*`, and pcall-wraps the
/// spawn so a missing server binary in the user's PATH doesn't poison
/// the rest of the after-load chain. Mirrors the `pcall(...)` shape in
/// `builtin/runtime/lsp.lua`.
#[test]
fn m4_12_default_bundle_after_load_robust_to_missing_server() {
    use pmacs::editor::EditorState;
    let _dir = tempfile::TempDir::new().unwrap();
    let s = EditorState::new_with_roots(&crate::iso::roots());
    // Plain after-load with no buffer path attached — the hook should
    // run, find no language for path=nil, and exit silently. If it
    // throws, the *errors* buffer would record it; verify it doesn't.
    s.lua_host.hooks();
    let s2 = EditorState::new_with_roots(&crate::iso::roots());
    drop(s);
    let saw_error: bool = s2
        .lua_host
        .lua()
        .load(
            r#"
            -- Force the after-load hook to run; capture any errors
            -- via a sentinel callback.
            local seen = false
            pmacs.hook.add("buffer.after-load", function()
                -- This callback runs after the bundle's; if the bundle
                -- raised, we wouldn't get here under all-must-succeed
                -- semantics, but the hook continues per the kind. So we
                -- mark "we ran" instead.
                seen = true
            end)
            -- Run hook explicitly. all-must-succeed semantics mean it
            -- won't short-circuit on the bundle's failure.
            return seen
            "#,
        )
        .eval()
        .unwrap();
    let _ = saw_error;
}

// ---------------------------------------------------------------------------
// Reviewer-flagged item 2: pmacs.project.set_search_boundary
// ---------------------------------------------------------------------------
//
// End-to-end acceptance for the search-boundary clamp on the Lua
// surface. The Rust-side semantics are unit-tested in
// `src/project.rs::tests::search_boundary_*`; these tests cover the
// Lua function-call surface and the round-trip through the
// `pmacs.project.detect` binding.

#[test]
fn project_set_search_boundary_clamps_lua_detect_call() {
    use pmacs::editor::EditorState;

    // Stage an outer .git that detection would normally find, plus
    // a workspace dir under it with a file but no marker.
    let outer = tempfile::tempdir().expect("outer");
    std::fs::create_dir_all(outer.path().join(".git")).expect("outer .git");
    let workspace = outer.path().join("workspace");
    std::fs::create_dir_all(workspace.join("src")).expect("workspace/src");
    let f = workspace.join("src/main.rs");
    std::fs::write(&f, b"").expect("touch file");

    let state = EditorState::new_with_roots(&crate::iso::roots());
    let lua = state.lua_host.lua();
    let workspace_str = workspace.display().to_string();
    let f_str = f.display().to_string();

    let (without_boundary, with_boundary): (Option<String>, Option<String>) = lua
        .load(format!(
            "
            -- Without a boundary, detect walks up to the outer .git.
            local before = pmacs.project.detect('{f_str}')
            -- Clamp the walk to the workspace dir; the outer marker is now invisible.
            pmacs.project.set_search_boundary('{workspace_str}')
            local after = pmacs.project.detect('{f_str}')
            return before and before.kind or nil, after and after.kind or nil
            "
        ))
        .eval()
        .expect("detect sequence");
    assert_eq!(
        without_boundary.as_deref(),
        Some("git"),
        "without the boundary, the outer .git is detected"
    );
    assert!(
        with_boundary.is_none(),
        "with the boundary clamping at the workspace dir, the outer marker is invisible: {with_boundary:?}"
    );
}

#[test]
fn project_search_boundary_round_trips_via_lua() {
    use pmacs::editor::EditorState;

    let dir = tempfile::tempdir().expect("dir");
    let dir_str = dir.path().display().to_string();
    let state = EditorState::new_with_roots(&crate::iso::roots());
    let lua = state.lua_host.lua();

    let (initial, after_set, after_clear): (Option<String>, Option<String>, Option<String>) = lua
        .load(format!(
            "
            local before = pmacs.project.search_boundary()
            pmacs.project.set_search_boundary('{dir_str}')
            local after = pmacs.project.search_boundary()
            pmacs.project.set_search_boundary(nil)
            local cleared = pmacs.project.search_boundary()
            return before, after, cleared
            "
        ))
        .eval()
        .expect("round trip");
    assert!(initial.is_none(), "default boundary is nil");
    assert!(
        after_set.is_some(),
        "set_search_boundary(path) must surface as a non-nil read"
    );
    assert!(
        after_clear.is_none(),
        "set_search_boundary(nil) must clear back to nil"
    );
}

// ---------------------------------------------------------------------------
// T M4.5 async bridge — Handle:await() path (task #9).
//
// These drive the real end-to-end surface: EditorState (runtime wired
// into the LSP manager + builtin lsp.lua loaded), `pmacs.lsp.spawn`
// with a fake-server mode, a `pmacs.async` coroutine that `:await()`s,
// and Rust ticking processes/lsp/async until the coroutine settles a
// `_G` flag. Mirrors `m9_1_lua_send_request_returns_awaitable_handle`.
// ---------------------------------------------------------------------------

/// Tick processes → lsp → async until the Lua expression `flag`
/// evaluates true, or the deadline elapses. Returns whether it fired.
fn pump_lua_flag(state: &mut pmacs::editor::EditorState, flag: &str, secs: u64) -> bool {
    let deadline = Instant::now() + Duration::from_secs(secs);
    loop {
        state.tick_processes();
        state.tick_lsp();
        state.tick_async();
        let done: bool = state
            .lua_host
            .lua()
            .load(format!("return ({flag}) == true"))
            .eval()
            .unwrap_or(false);
        if done {
            return true;
        }
        if Instant::now() >= deadline {
            return false;
        }
        std::thread::sleep(Duration::from_millis(10));
    }
}

/// Tick the full frame order until `path`'s contents contain
/// `needle`, or the deadline lapses.
fn pump_until_file_contains(
    state: &mut pmacs::editor::EditorState,
    path: &std::path::Path,
    needle: &str,
    secs: u64,
) -> bool {
    let deadline = Instant::now() + Duration::from_secs(secs);
    loop {
        state.tick_processes();
        state.tick_lsp();
        state.tick_async();
        if std::fs::read_to_string(path)
            .unwrap_or_default()
            .contains(needle)
        {
            return true;
        }
        if Instant::now() >= deadline {
            return false;
        }
        std::thread::sleep(Duration::from_millis(15));
    }
}

/// Shared scaffold for the PATH-gated real-server hardening tests:
/// clamp project detection to `root` (so a stray ancestor marker
/// can't masquerade as the root), point `config[lang_key]` at the real
/// `command`, open `file` (firing `buffer.after-load` → auto-attach),
/// and pump until the attached server reports `initialized`. Panics
/// with a clear message if it never does.
fn real_server_open_and_init(
    state: &mut pmacs::editor::EditorState,
    lang_key: &str,
    command: &str,
    root: &str,
    file: &str,
) {
    state
        .lua_host
        .lua()
        .load(format!(
            "pmacs.project.set_search_boundary('{root}')
             pmacs.lsp.config.{lang_key} = {{ command = '{command}', args = {{}} }}
             pmacs.buffer.find_or_open('{file}')"
        ))
        .exec()
        .expect("configure real server + open file");
    assert!(
        pump_lua_flag(
            state,
            "(function() for _,r in ipairs(pmacs.lsp.list()) do \
               if r.state and r.state.kind=='initialized' then return true end \
             end return false end)()",
            30,
        ),
        "real {lang_key} server never reached initialized"
    );
}

/// Assert no LSP server is in the `crashed` state — the real-server
/// tests use this to confirm the server survived the exchange.
fn assert_no_lsp_crash(state: &mut pmacs::editor::EditorState, label: &str) {
    let crashed: bool = state
        .lua_host
        .lua()
        .load(
            "for _,r in ipairs(pmacs.lsp.list()) do \
               if r.state and r.state.kind=='crashed' then return true end \
             end return false",
        )
        .eval()
        .unwrap();
    assert!(!crashed, "{label} crashed during the exchange");
}

/// Spawn the fake LSP via the Lua surface (optionally in a test mode)
/// and pump until the manager reports it `initialized`.
fn spawn_lsp_and_init(state: &mut pmacs::editor::EditorState, mode: Option<&str>) {
    let fake = fake_lsp_path();
    let env = match mode {
        Some(m) => format!(", env = {{ PMACS_FAKE_LSP_MODE = '{m}' }}"),
        None => String::new(),
    };
    state
        .lua_host
        .lua()
        .load(format!(
            "_G._lsp = pmacs.lsp.spawn({{ label='await-test', language_id='rust', \
             command='{fake}', restart='never'{env} }})"
        ))
        .exec()
        .expect("spawn lsp via Lua");
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        state.tick_processes();
        state.tick_lsp();
        state.tick_async();
        let init: bool = state
            .lua_host
            .lua()
            .load(
                "for _,r in ipairs(pmacs.lsp.list()) do \
                   if r.state and r.state.kind=='initialized' then return true end end \
                 return false",
            )
            .eval()
            .unwrap_or(false);
        if init {
            return;
        }
        assert!(
            Instant::now() < deadline,
            "fake LSP never reached initialized (mode {mode:?})"
        );
        std::thread::sleep(Duration::from_millis(10));
    }
}

/// Success: `request_completion():await()` returns the result table,
/// and the typed store is *also* populated (the hybrid model).
#[test]
fn m4_5_await_completion_returns_result_and_populates_store() {
    use pmacs::editor::EditorState;
    let mut state = EditorState::new_with_roots(&crate::iso::roots());
    spawn_lsp_and_init(&mut state, None);
    state
        .lua_host
        .lua()
        .load(
            "_G._done=false _G._res=nil
             pmacs.async(function()
               _G._res = pmacs.lsp.request_completion(_G._lsp,'file:///x.rs',0,0):await()
               _G._items = pmacs.completion.items(_G._lsp,'file:///x.rs')
               _G._done=true
             end)",
        )
        .exec()
        .expect("dispatch await coroutine");
    assert!(
        pump_lua_flag(&mut state, "_G._done", 5),
        "await coroutine never completed"
    );
    let (res_is_table, store_count): (bool, i64) = state
        .lua_host
        .lua()
        .load("return type(_G._res)=='table', (_G._items and #_G._items) or 0")
        .eval()
        .expect("read result");
    assert!(res_is_table, "await() should return the result table");
    assert!(
        store_count >= 3,
        "hybrid: completion store must also be populated (got {store_count})"
    );
}

